From 310ad048a4c3825edf4dde599b77fb31b3ad82ad Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:18:31 +0100
Subject: [PATCH] libtaskmanager: ignore launchers on other activities when
 sorting

Windows were sorted into the slot of a launcher pinned only on another
activity, so they jumped to the front. Now only launchers on the current
activity count when sorting, and tasks are re-sorted when it changes.

BUG: 386055
---
 libtaskmanager/tasksmodel.cpp | 38 ++++++++++++++++++++++++++++++-----
 1 file changed, 33 insertions(+), 5 deletions(-)

diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..eef9edee5e 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -85,6 +85,7 @@ public:
     void forceResort();
     bool lessThan(const QModelIndex &left, const QModelIndex &right, bool sortOnlyLaunchers = false) const;
     std::optional<bool> lessThanByVirtualDesktop(const QModelIndex &left, const QModelIndex &right) const;
+    int launcherPositionOnActivity(const QUrl &url) const;

 private:
     TasksModel *const q;
@@ -272,6 +273,17 @@ void TasksModel::Private::initModels()
     QObject::connect(filterProxyModel, &TaskFilterProxyModel::filterHiddenChanged, q, &TasksModel::filterHiddenChanged);
     QObject::connect(filterProxyModel, &TaskFilterProxyModel::hideActivatedLaunchersChanged, q, &TasksModel::hideActivatedLaunchersChanged);

+    // Sorting by launcher position only considers launchers on the current activity,
+    // so window tasks may need to move in or out of the launcher area.
+    const auto resortForActivity = [this]() {
+        if (sortMode == SortManual && (launchInPlace || !separateLaunchers)) {
+            updateManualSortMap();
+            forceResort();
+        }
+    };
+    QObject::connect(filterProxyModel, &TaskFilterProxyModel::activityChanged, q, resortForActivity);
+    QObject::connect(filterProxyModel, &TaskFilterProxyModel::filterByActivityChanged, q, resortForActivity);
+
     groupingProxyModel = new TaskGroupingProxyModel(q);
     groupingProxyModel->setSourceModel(filterProxyModel);
     QObject::connect(groupingProxyModel, &TaskGroupingProxyModel::groupModeChanged, q, &TasksModel::groupModeChanged);
@@ -478,7 +490,8 @@ void TasksModel::Private::updateManualSortMap()
                     // An exception is a launcher that is hidden because it has a matching
                     // running task: when launchers are not kept separate the
                     // new task should be where the launcher was.
-                    const bool isActivatedLauncher = concatProxyIndex.data(AbstractTasksModel::IsLauncher).toBool() && q->hideActivatedLaunchers();
+                    const bool isActivatedLauncher = concatProxyIndex.data(AbstractTasksModel::IsLauncher).toBool() && q->hideActivatedLaunchers()
+                        && launcherPositionOnActivity(concatProxyIndex.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl()) != -1;

                     if (appsMatch(concatProxyIndex, idx) && (isActivatedLauncher || filterProxyModel->acceptsRow(concatProxyIndex.row()))) {
                         sortedPreFilterRows.move(row, j + 1);
@@ -499,7 +512,7 @@ void TasksModel::Private::updateManualSortMap()
                     const QModelIndex &concatProxyIndex = concatProxyModel->index(sortedPreFilterRows.at(j), 0);

                     if (concatProxyIndex.data(AbstractTasksModel::IsLauncher).toBool()
-                        || launcherTasksModel->launcherPosition(concatProxyIndex.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl()) != -1) {
+                        || launcherPositionOnActivity(concatProxyIndex.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl()) != -1) {
                         insertPos = j + 1;
                     } else {
                         break;
@@ -728,6 +741,21 @@ std::optional<bool> TasksModel::Private::lessThanByVirtualDesktop(const QModelIn
     return std::nullopt;
 }

+int TasksModel::Private::launcherPositionOnActivity(const QUrl &url) const
+{
+    const int pos = q->launcherPosition(url);
+
+    if (pos != -1 && filterProxyModel->filterByActivity() && !q->activity().isEmpty()) {
+        const QStringList activities = launcherTasksModel->launcherActivities(url);
+
+        if (!activities.contains(NULL_UUID) && !activities.contains(q->activity())) {
+            return -1;
+        }
+    }
+
+    return pos;
+}
+
 bool TasksModel::Private::lessThan(const QModelIndex &left, const QModelIndex &right, bool sortOnlyLaunchers) const
 {
     // Launcher tasks go first.
@@ -742,8 +770,8 @@ bool TasksModel::Private::lessThan(const QModelIndex &left, const QModelIndex &r
             return (left.row() < right.row());
         }

-        const int leftPos = q->launcherPosition(left.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
-        const int rightPos = q->launcherPosition(right.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
+        const int leftPos = launcherPositionOnActivity(left.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());
+        const int rightPos = launcherPositionOnActivity(right.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl());

         if (leftIsLauncher && !rightIsLauncher) {
             if (launchInPlace) {
@@ -1645,7 +1673,7 @@ bool TasksModel::move(int row, int newPos, const QModelIndex &parent)
             // When using launch-in-place sorting, launcher-backed window tasks act as launchers.
         } else if ((d->launchInPlace || !d->separateLaunchers) && idx.data(AbstractTasksModel::IsWindow).toBool()) {
             const QUrl &launcherUrl = idx.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl();
-            const int launcherPos = launcherPosition(launcherUrl);
+            const int launcherPos = d->launcherPositionOnActivity(launcherUrl);

             if (launcherPos != -1) {
                 isLauncherMove = true;
